#include <algorithm>
#include <cstddef>
#include <iostream>
#include <span>
#include <string_view>
#include <utility>

// Owns an array of ints through a raw pointer: a resource handle, the one kind of class where new[] and delete[] belong.
class IntBuffer {
 public:
  explicit IntBuffer(std::ptrdiff_t size) : size_(size), data_(new int[size]{}) {}
  ~IntBuffer() { delete[] data_; }

  IntBuffer(const IntBuffer& other) : size_(other.size_), data_(new int[other.size_]) {
    std::ranges::copy(other.values(), data_);
  }
  IntBuffer& operator=(const IntBuffer& other) {
    IntBuffer copy(other);  // the only step that can throw, and *this is still untouched
    swap(copy);
    return *this;  // copy's destructor frees the old array
  }

  IntBuffer(IntBuffer&& other) noexcept
      : size_(std::exchange(other.size_, 0)), data_(std::exchange(other.data_, nullptr)) {}
  IntBuffer& operator=(IntBuffer&& other) noexcept {
    IntBuffer taken(std::move(other));  // empties other, even when other is *this
    swap(taken);
    return *this;
  }

  void swap(IntBuffer& other) noexcept {
    std::swap(size_, other.size_);
    std::swap(data_, other.data_);
  }
  friend void swap(IntBuffer& a, IntBuffer& b) noexcept { a.swap(b); }

  [[nodiscard]] std::span<int> values() { return {data_, static_cast<std::size_t>(size_)}; }
  [[nodiscard]] std::span<const int> values() const { return {data_, static_cast<std::size_t>(size_)}; }

 private:
  std::ptrdiff_t size_;
  int* data_;
};

void show(std::string_view label, const IntBuffer& buffer) {
  std::cout << label << ':';
  for (const int v : buffer.values()) std::cout << ' ' << v;
  std::cout << '\n';
}

// Assign through two references, which is how self-assignment reaches real code.
void copy_into(IntBuffer& target, const IntBuffer& source) { target = source; }
void move_into(IntBuffer& target, IntBuffer& source) { target = std::move(source); }

int main() {
  IntBuffer a(3);
  a.values()[0] = 7;
  IntBuffer b = a;
  b.values()[1] = 8;
  show("a", a);
  show("b", b);

  IntBuffer c(5);
  c = b;
  IntBuffer d = std::move(c);
  show("c after the move", c);
  show("d", d);

  copy_into(d, d);
  move_into(d, d);
  show("d after self-assignment and self-move", d);
}

