#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <utility>

// IntBuffer from the answer, with a line printed wherever memory changes hands.
class IntBuffer {
 public:
  explicit IntBuffer(std::ptrdiff_t size) : size_(size), data_(new int[size]{}) {
    std::cout << std::format("  constructor: allocate {} ints\n", size_);
  }
  ~IntBuffer() {
    if (data_ == nullptr) {
      std::cout << "  destructor: nothing to free\n";
    } else {
      std::cout << std::format("  destructor: free {} ints\n", size_);
    }
    delete[] data_;
  }

  IntBuffer(const IntBuffer& other) : size_(other.size_), data_(new int[other.size_]) {
    std::cout << std::format("  copy constructor: allocate {} ints, copy them\n", size_);
    std::ranges::copy(other.values(), data_);
  }
  IntBuffer& operator=(const IntBuffer& other) {
    std::cout << "  copy assignment: copy, then swap\n";
    IntBuffer copy(other);
    swap(copy);
    return *this;
  }

  IntBuffer(IntBuffer&& other) noexcept
      : size_(std::exchange(other.size_, 0)), data_(std::exchange(other.data_, nullptr)) {
    std::cout << std::format("  move constructor: take {} ints\n", size_);
  }
  IntBuffer& operator=(IntBuffer&& other) noexcept {
    std::cout << "  move assignment: move, then swap\n";
    IntBuffer taken(std::move(other));
    swap(taken);
    return *this;
  }

  void swap(IntBuffer& other) noexcept {
    std::swap(size_, other.size_);
    std::swap(data_, other.data_);
  }

  [[nodiscard]] std::span<int> values() { return {data_, static_cast<std::size_t>(size_)}; }
  [[nodiscard]] std::span<const int> values() const { return {data_, static_cast<std::size_t>(size_)}; }

 private:
  std::ptrdiff_t size_;
  int* data_;
};

[[nodiscard]] IntBuffer make_ramp(std::ptrdiff_t size) {
  IntBuffer ramp(size);
  int next = 0;
  for (int& v : ramp.values()) v = next++;
  return ramp;
}

int main() {
  std::cout << "IntBuffer a = make_ramp(3);\n";
  IntBuffer a = make_ramp(3);
  std::cout << "IntBuffer b = a;\n";
  IntBuffer b = a;
  std::cout << "IntBuffer c(5); c = a;\n";
  IntBuffer c(5);
  c = a;
  std::cout << "IntBuffer d = std::move(a);\n";
  IntBuffer d = std::move(a);
  std::cout << "b = std::move(d);\n";
  b = std::move(d);
  std::cout << "end of main\n";
}

#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <new>
#include <span>
#include <string_view>
#include <utility>
#include <vector>

// Owns a raw array of sensor samples.
class Samples {
 public:
  Samples() = default;
  explicit Samples(std::ptrdiff_t size) : size_(size), data_(new std::int16_t[size]{}) {}  // zero-filled
  explicit Samples(std::span<const std::int16_t> values) : Samples(std::ssize(values)) {
    std::ranges::copy(values, data_);
  }
  ~Samples() { delete[] data_; }

  Samples(const Samples& other) : Samples(other.view()) {}
  Samples& operator=(const Samples& other) {
    Samples copy(other);
    swap(copy);
    return *this;
  }
  Samples(Samples&& other) noexcept
      : size_(std::exchange(other.size_, 0)), data_(std::exchange(other.data_, nullptr)) {}
  Samples& operator=(Samples&& other) noexcept {
    Samples taken(std::move(other));
    swap(taken);
    return *this;
  }

  void swap(Samples& other) noexcept {
    std::swap(size_, other.size_);
    std::swap(data_, other.data_);
  }
  friend void swap(Samples& a, Samples& b) noexcept { a.swap(b); }

  // Keeps the first min(size, new_size) samples and zero-fills the rest. If the allocation
  // throws, *this is unchanged: the strong guarantee.
  void resize(std::ptrdiff_t new_size) {
    Samples resized(new_size);
    std::ranges::copy(view().first(static_cast<std::size_t>(std::min(size_, new_size))), resized.data_);
    swap(resized);
  }

  [[nodiscard]] std::span<std::int16_t> view() { return {data_, static_cast<std::size_t>(size_)}; }
  [[nodiscard]] std::span<const std::int16_t> view() const { return {data_, static_cast<std::size_t>(size_)}; }

 private:
  std::ptrdiff_t size_ = 0;
  std::int16_t* data_ = nullptr;
};

void show(std::string_view label, const Samples& samples) {
  std::cout << label << ':';
  for (const std::int16_t s : samples.view()) std::cout << ' ' << s;
  std::cout << '\n';
}

void copy_into(Samples& target, const Samples& source) { target = source; }
void move_into(Samples& target, Samples& source) { target = std::move(source); }

int main() {
  constexpr std::array<std::int16_t, 4> raw{812, 790, 1204, 655};
  Samples scan(raw);

  // 1. Copies are deep.
  Samples copy = scan;
  copy.view()[0] = 0;
  show("1 scan", scan);
  show("1 copy", copy);

  // 2. A moved-from object is empty and can be assigned again.
  Samples moved = std::move(copy);
  show("2 copy after the move", copy);
  copy = scan;
  show("2 copy reassigned", copy);

  // 3. Self-assignment and self-move keep the value.
  copy_into(scan, scan);
  move_into(scan, scan);
  show("3 scan", scan);

  // 4. Growth moves the elements: the first scan keeps its array.
  std::vector<Samples> scans;
  scans.push_back(scan);
  const std::int16_t* const before = scans.front().view().data();
  scans.push_back(scan);  // capacity 1 -> 2: the first element is relocated
  std::cout << "4 after growth: " << (scans.front().view().data() == before ? "same array, moved" : "new array, copied")
            << '\n';

  // 5. resize keeps a prefix, and a failed allocation leaves the samples as they were.
  scan.resize(6);
  show("5 grown", scan);
  scan.resize(2);
  show("5 shrunk", scan);
  try {
    scan.resize(-1);
  } catch (const std::bad_alloc& e) {
    std::cout << "5 resize(-1) threw " << e.what() << '\n';
  }
  show("5 unchanged", scan);
}

#include <concepts>
#include <cstddef>
#include <iostream>
#include <span>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

// The IntBuffer of the answer, with the vector doing the owning: no special members at all.
class IntBuffer {
 public:
  explicit IntBuffer(std::ptrdiff_t size) : values_(static_cast<std::size_t>(size)) {}
  [[nodiscard]] std::span<int> values() { return values_; }
  [[nodiscard]] std::span<const int> values() const { return values_; }

 private:
  std::vector<int> values_;
};

static_assert(std::copyable<IntBuffer>);
static_assert(std::is_nothrow_move_constructible_v<IntBuffer> && std::is_nothrow_move_assignable_v<IntBuffer>);

void show(std::string_view label, const IntBuffer& buffer) {
  std::cout << label << ':';
  for (const int v : buffer.values()) std::cout << ' ' << v;
  std::cout << '\n';
}

void copy_into(IntBuffer& target, const IntBuffer& source) { target = source; }

int main() {
  IntBuffer a(3);
  a.values()[0] = 7;
  IntBuffer b = a;
  b.values()[1] = 8;
  show("a", a);
  show("b", b);
  const IntBuffer c = std::move(b);
  show("b after the move", b);
  show("c", c);
  copy_into(a, a);
  show("a after self-assignment", a);
}

#include <concepts>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <format>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>

struct Scan {
  std::string frame;
  std::vector<std::int32_t> ranges_mm;
};

// Writes one line per scan to a log file it owns.
class ScanRecorder {
 public:
  explicit ScanRecorder(const std::filesystem::path& path) : log_(std::fopen(path.c_str(), "w")) {
    if (!log_) throw std::runtime_error("cannot open " + path.string());
  }
  void record(Scan scan) {
    std::fputs(std::format("{} {}\n", scan.frame, scan.ranges_mm.size()).c_str(), log_.get());
    scans_.push_back(std::move(scan));
  }
  [[nodiscard]] std::ptrdiff_t count() const { return std::ssize(scans_); }

 private:
  struct Closer {
    void operator()(std::FILE* f) const noexcept { std::fclose(f); }
  };
  std::vector<Scan> scans_;
  std::unique_ptr<std::FILE, Closer> log_;
};

static_assert(std::copyable<Scan> && std::is_nothrow_move_constructible_v<Scan>);
static_assert(!std::is_copy_constructible_v<ScanRecorder> && !std::is_copy_assignable_v<ScanRecorder>);
static_assert(std::is_nothrow_move_constructible_v<ScanRecorder> && std::is_nothrow_move_assignable_v<ScanRecorder>);

[[nodiscard]] ScanRecorder open_recorder(const std::filesystem::path& path) { return ScanRecorder(path); }

int main() {
  const Scan first{.frame = "front_lidar", .ranges_mm = {812, 790, 1204}};
  Scan copy = first;
  copy.ranges_mm.push_back(655);
  std::cout << std::format("first has {} ranges, copy has {}\n", first.ranges_mm.size(), copy.ranges_mm.size());

  std::vector<ScanRecorder> recorders;
  recorders.push_back(open_recorder("front.log"));
  recorders.front().record(first);
  recorders.front().record(std::move(copy));
  recorders.push_back(open_recorder("rear.log"));  // growth moves the first recorder
  std::cout << std::format("front recorder holds {} scans\n", recorders.front().count());
}

#include <cstddef>

// A destructor and nothing else: the compiler still writes a copy constructor, and it copies the pointer.
class IntBuffer {
 public:
  explicit IntBuffer(std::ptrdiff_t size) : size_(size), data_(new int[size]{}) {}
  ~IntBuffer() { delete[] data_; }
  [[nodiscard]] std::ptrdiff_t size() const { return size_; }

 private:
  std::ptrdiff_t size_;
  int* data_;
};

int main() {
  const IntBuffer a(3);
  const IntBuffer b = a;  // both now point at one array, and both destructors free it
  return b.size() == 3 ? 0 : 1;
}

#include <algorithm>
#include <cstddef>
#include <span>

class IntBuffer {
 public:
  explicit IntBuffer(std::ptrdiff_t size) : size_(size), data_(new int[size]{}) {}
  ~IntBuffer() { delete[] data_; }
  IntBuffer(const IntBuffer& other) : size_(other.size_), data_(new int[other.size_]) {
    std::ranges::copy(other.values(), data_);
  }
  IntBuffer& operator=(const IntBuffer& other) {
    delete[] data_;  // frees first
    int* const fresh = new int[other.size_];
    std::ranges::copy(other.values(), fresh);  // when other is *this, this reads the array freed above
    data_ = fresh;
    size_ = other.size_;
    return *this;
  }
  [[nodiscard]] std::span<const int> values() const { return {data_, static_cast<std::size_t>(size_)}; }

 private:
  std::ptrdiff_t size_;
  int* data_;
};

// Assigns through two references, so nothing at the call site looks like self-assignment.
void copy_into(IntBuffer& target, const IntBuffer& source) { target = source; }

int main() {
  IntBuffer a(3);
  copy_into(a, a);
}

#include <format>
#include <iostream>
#include <string_view>
#include <utility>
#include <vector>

struct Counts {
  int copies = 0;
  int moves = 0;
};

// Copyable, and the move promises not to throw.
class NoexceptMove {
 public:
  explicit NoexceptMove(Counts& counts) : counts_(&counts) {}
  NoexceptMove(const NoexceptMove& other) : counts_(other.counts_) { ++counts_->copies; }
  NoexceptMove(NoexceptMove&& other) noexcept : counts_(other.counts_) { ++counts_->moves; }
  NoexceptMove& operator=(const NoexceptMove&) = default;
  NoexceptMove& operator=(NoexceptMove&&) noexcept = default;
  ~NoexceptMove() = default;

 private:
  Counts* counts_;
};

// Copyable, and the move may throw.
class ThrowingMove {
 public:
  explicit ThrowingMove(Counts& counts) : counts_(&counts) {}
  ThrowingMove(const ThrowingMove& other) : counts_(other.counts_) { ++counts_->copies; }
  ThrowingMove(ThrowingMove&& other) : counts_(other.counts_) { ++counts_->moves; }
  ThrowingMove& operator=(const ThrowingMove&) = default;
  ThrowingMove& operator=(ThrowingMove&&) = default;
  ~ThrowingMove() = default;

 private:
  Counts* counts_;
};

// Move-only, and the move may throw.
class MoveOnly {
 public:
  explicit MoveOnly(Counts& counts) : counts_(&counts) {}
  MoveOnly(const MoveOnly&) = delete;
  MoveOnly(MoveOnly&& other) : counts_(other.counts_) { ++counts_->moves; }
  MoveOnly& operator=(const MoveOnly&) = delete;
  MoveOnly& operator=(MoveOnly&&) = default;
  ~MoveOnly() = default;

 private:
  Counts* counts_;
};

struct Track {  // declares nothing
  NoexceptMove points;
};

struct TrackWithDestructor {  // someone added a destructor to set a breakpoint in
  NoexceptMove points;
  ~TrackWithDestructor() = default;
};

template <typename T>
void grow(std::string_view name) {
  Counts counts;
  std::vector<T> v;
  for (int i = 0; i < 20; ++i) v.emplace_back(counts);
  std::cout << std::format("{:<15}copies {:>2}, moves {:>2}, capacity {}\n", name, counts.copies, counts.moves,
                           v.capacity());
}

template <typename T>
void move_once(std::string_view name) {
  Counts counts;
  T a{NoexceptMove(counts)};
  [[maybe_unused]] const T b = std::move(a);
  std::cout << std::format("{:<21}copies {}, moves {}\n", name, counts.copies, counts.moves);
}

int main() {
  grow<NoexceptMove>("noexcept move");
  grow<ThrowingMove>("throwing move");
  grow<MoveOnly>("move-only");
  move_once<Track>("Track");
  move_once<TrackWithDestructor>("TrackWithDestructor");
}

